<template><main class="container page-section"><div v-if="!user" class="empty">正在载入主页…</div><template v-else><section class="profile card"><UserAvatar :src="user.avatar_url || user.avatar_path" :name="user.username" :size="72"/><div><p class="eyebrow">个人博客</p><h1 class="page-title">{{user.blog_title||user.username}}</h1><p class="muted">{{user.bio||'这个作者暂时还没有留下简介。'}}</p><p class="muted">{{user.post_count}} 篇公开文章 · {{user.follower_count}} 位关注者</p></div><button v-if="!mine" class="button" @click="follow">{{user.following?'已关注':'关注'}}</button></section><section><div class="section-heading"><h2>公开文章</h2><RouterLink v-if="!archive" :to="`/u/${route.params.username}/posts`">查看归档</RouterLink></div><div v-if="!posts.length" class="empty">尚未发布公开文章。</div><div v-else class="list"><RouterLink v-for="post in posts" :key="post.id" class="post card" :to="`/posts/${post.slug}`"><small>{{date(post.published_at)}} · {{post.reading_minutes}} 分钟</small><h3>{{post.title}}</h3><p>{{post.excerpt}}</p></RouterLink></div></section></template></main></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute,RouterLink}from'vue-router';import http from'@/services/http';import UserAvatar from'@/components/UserAvatar.vue';const route=useRoute(),user=ref<any>(),posts=ref<any[]>([]),mine=computed(()=>JSON.parse(localStorage.getItem('userInfo')||'{}').blog_slug===route.params.username),archive=computed(()=>route.path.endsWith('/posts')),date=(v:string)=>new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(v));async function load(){try{user.value=(await http.get(`/api/public/users/${route.params.username}`)).data.user;posts.value=(await http.get(`/api/public/users/${route.params.username}/posts`)).data.items}catch{}}async function follow(){if(!localStorage.getItem('isLoggedIn'))return location.assign('/login');if(user.value.following)await http.delete(`/api/users/${route.params.username}/follow`);else await http.post(`/api/users/${route.params.username}/follow`);user.value.following=!user.value.following}onMounted(load)</script>
<style scoped>.profile{padding:28px;display:flex;align-items:center;gap:20px;margin-bottom:42px}.profile .button{margin-left:auto}.section-heading{display:flex;justify-content:space-between;align-items:center}.list{display:grid;gap:10px}.post{padding:18px;text-decoration:none}.post:hover{border-color:var(--accent)}.post h3{margin:4px 0}.post p,small{color:var(--muted)}@media(max-width:600px){.profile{align-items:start;flex-wrap:wrap}.profile .button{margin-left:92px}}</style>
